import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        var n = sc.nextInt();
        var list = new ArrayList<Integer>();
        for (var i = 0; i < n; i++) {
            list.add(sc.nextInt());
        }
        var sum = 0;
        for (var num : list) {
            sum += num;
        }
        var average = (double) sum / n;
        System.out.println(average);
    }
}
